exercises.reference:
import re

AW = {"H": 1.008, "C": 12.011, "N": 14.007, "O": 15.999, "Mg": 24.305, "Al": 26.982,
      "P": 30.974, "S": 32.06, "K": 39.098, "Ca": 40.078, "Fe": 55.845}

def molar_mass(formula):
    """Molar mass in g/mol of a formula such as 'Ca(OH)2' or 'K4(Fe(CN)6)'."""
    stack = [0.0]
    for symbol, count, open_, close, mult in re.findall(r"([A-Z][a-z]?)(\d*)|(\()|(\))(\d*)", formula):
        if open_:
            stack.append(0.0)
        elif close:
            inner = stack.pop()
            stack[-1] += inner * int(mult or 1)
        else:
            stack[-1] += AW[symbol] * int(count or 1)
    assert len(stack) == 1, "unbalanced brackets"
    return stack[0]
